class Super {
    int id;
    public boolean equals(Object o) { return o instanceof Super s && id == s.id; }
}
class Sub extends Super {
    String val;
    public boolean equals(Object o) { return o instanceof Sub s && super.equals(o) && val.equals(s.val); }
}

