class User {
    int id;
    // Bug check
    public boolean equals(User other) {
        return this.id == other.id;
    }
}

class BadKey {
    int id;
    BadKey(int id) { this.id = id; }
    @Override
    public boolean equals(Object o) {
        return o instanceof BadKey other && id == other.id;
    }
    @Override
    public int hashCode() {
        return 42;
    }
}

class Point {
    int x, y;
    Point(int x, int y) { this.x = x; this.y = y; }
    @Override
    public boolean equals(Object o) { return o instanceof Point p && x == p.x && y == p.y; }
}
class ColorPoint extends Point {
    String color;
    ColorPoint(int x, int y, String c) { super(x, y); color = c; }
    @Override
    public boolean equals(Object o) { return o instanceof ColorPoint cp && super.equals(o) && color.equals(cp.color); }
}
